svg=f'''<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="630" viewBox="0 0 1200 630"><defs><linearGradient id="bg" x2="1" y2="1"><stop stop-color="#1c1b15"/><stop offset=".6" stop-color="#0b0d0c"/><stop offset="1" stop-color="#26231b"/></linearGradient><linearGradient id="gold"><stop stop-color="#f2dfb3"/><stop offset="1" stop-color="#b79a5f"/></linearGradient><radialGradient id="halo"><stop stop-color="#d5b973" stop-opacity=".16"/><stop offset="1" stop-color="#d5b973" stop-opacity="0"/></radialGradient></defs><rect width="1200" height="630" fill="url(#bg)"/><ellipse cx="920" cy="240" rx="460" ry="390" fill="url(#halo)"/><g stroke="#c7aa64" opacity=".12" fill="none"><ellipse cx="1020" cy="330" rx="410" ry="260"/><ellipse cx="1020" cy="330" rx="370" ry="220"/></g><path d="M48 48H1152V582H48Z" fill="none" stroke="#c3a76b" stroke-opacity=".26"/><image href="{image('public/assets/baccarat-logo.png','image/png')}" x="68" y="66" width="48" height="48"/><g font-family="Noto Sans CJK TC,sans-serif"><text x="132" y="88" fill="#e9d6ab" font-size="20" font-weight="500">御策百家輔助</text><text x="132" y="110" fill="#a9976b" font-size="10" letter-spacing="3">MT ASSISTANT</text><text x="72" y="218" fill="#bcab7e" font-size="12" letter-spacing="3">MT MATRIX / MT AUTO</text><text x="68" y="291" fill="url(#gold)" font-size="55" font-weight="bold">資訊清楚，操作有序。</text><text x="72" y="343" fill="#c7c4b5" font-size="22">多桌觀察・條件管理・完整操作教學</text><rect x="72" y="391" width="176" height="45" rx="7" fill="url(#gold)"/><text x="102" y="420" fill="#282a21" font-size="17" font-weight="500">探索御策工具 →</text><text x="72" y="538" fill="#978c72" font-size="12">真實程式介面　／　iPhone・Android・電腦適用</text><text x="72" y="559" fill="#786f5e" font-size="10">分析與配注策略僅供輔助，不保證預測結果或獲利。</text></g><rect x="646" y="174" width="495" height="326" rx="14" fill="#101917" stroke="#a8945e" stroke-opacity=".6"/><image href="{image('public/assets/interfaces/matrix-assist.png','image/png')}" x="664" y="199" width="459" height="276" preserveAspectRatio="xMidYMid meet"/></svg>'''
